import { Accessor, Setter } from 'solid-js';
import { Values, Modify } from '@solid-primitives/utils';

type GenericListener<Payload extends any[] = []> = (...payload: Payload) => void;
type Listen<A0 = void, A1 = void, A2 = void> = (listener: void extends A0 ? GenericListener : void extends A1 ? GenericListener<[A0]> : void extends A2 ? GenericListener<[A0, A1]> : GenericListener<[A0, A1, A2]>) => VoidFunction;
type ListenProtect<A0 = void, A1 = void, A2 = void> = (listener: Parameters<Listen<A0, A1, A2>>[0], protect?: boolean) => VoidFunction;
type GenericListen<Payload extends any[] = []> = (listener: GenericListener<Payload>) => VoidFunction;
type GenericListenProtect<Payload extends any[] = []> = (listener: GenericListener<Payload>, protect?: boolean) => VoidFunction;
type Emit<A0 = void, A1 = void, A2 = void> = void extends A0 ? () => void : void extends A1 ? (payload: A0) => void : void extends A2 ? GenericEmit<[A0, A1]> : GenericEmit<[A0, A1, A2]>;
type GenericEmit<Payload extends any[] = []> = (...payload: Payload) => void;
type Remove<A0 = void, A1 = void, A2 = void> = (listener: GenericListener<[A0, A1, A2]>) => boolean;
type EmitGuard<A0 = void, A1 = void, A2 = void> = {
    (emit: {
        (arg0: A0, arg1: A1, arg2: A2): void;
        (): void;
    }, ...payload: [A0, A1, A2]): void;
};
type RemoveGuard<Listener extends Function> = (remove: () => boolean, listener: Listener) => boolean;

/**
 * Very minimal interface for emiting and receiving events. Good for parent-child component communication.
 *
 * @returns `[listen, emit, clear]`
 *
 * @see https://github.com/solidjs-community/solid-primitives/tree/main/packages/event-bus#createSimpleEmitter
 *
 * @example
// accepts up-to-3 genetic payload types
const [listen, emit, clear] = createSimpleEmitter<string, number, boolean>();

listen((a, b, c) => console.log(a, b, c));

emit("foo", 123, true);

// clear all listeners
clear();
 */
declare function createSimpleEmitter<A0 = void, A1 = void, A2 = void>(initial?: GenericListener<[A0, A1, A2]>[]): [listen: GenericListen<[A0, A1, A2]>, emit: GenericEmit<[A0, A1, A2]>, clear: VoidFunction];

type Emitter<A0 = void, A1 = void, A2 = void> = {
    listen: GenericListenProtect<[A0, A1, A2]>;
    emit: GenericEmit<[A0, A1, A2]>;
    remove: Remove<A0, A1, A2>;
    clear: VoidFunction;
    has: (listener: GenericListener<[A0, A1, A2]>) => boolean;
    value: () => void;
};
type EmitterConfig<A0 = void, A1 = void, A2 = void> = {
    emitGuard?: EmitGuard<A0, A1, A2>;
    removeGuard?: RemoveGuard<GenericListener<[A0, A1, A2]>>;
    beforeEmit?: GenericListener<[A0, A1, A2]>;
};
/**
 * Provides all the base functions of an event-emitter, plus additional functions for managing listeners, it's behavior could be customized with an config object.
 *
 * @param config Emitter configuration: `emitGuard`, `removeGuard`, `beforeEmit` functions.
 *
 * @returns the emitter: `{listen, once, emit, remove, clear, has}`
 *
 * @see https://github.com/solidjs-community/solid-primitives/tree/main/packages/event-bus#createEmitter
 *
 * @example
// accepts up-to-3 genetic payload types
const emitter = createEmitter<string, number, boolean>();
// emitter can be destructured:
const { listen, emit, has, clear } = emitter;

const listener = (a, b, c) => console.log(a, b, c);
emitter.listen(listener);

emitter.emit("foo", 123, true);

emitter.remove(listener);
emitter.has(listener); // false
 */
declare function createEmitter<A0 = void, A1 = void, A2 = void>(config?: EmitterConfig<A0, A1, A2>): Emitter<A0, A1, A2>;

type EventBusListener<Event, V = Event | undefined> = GenericListener<[Event, V]>;
type EventBusListen<Event, V = Event | undefined> = ListenProtect<Event, V>;
type EventBusRemove<Event, V = Event | undefined> = (listener: EventBusListener<Event, V>) => boolean;
type EventBus<Event, V = Event | undefined> = {
    remove: EventBusRemove<Event, V>;
    listen: EventBusListen<Event, V>;
    emit: GenericEmit<[Event]>;
    clear: VoidFunction;
    has: (listener: EventBusListener<Event, V>) => boolean;
    value: Accessor<V>;
};
/**
 * Provides all the base functions of an event-emitter, functions for managing listeners, it's behavior could be customized with an config object.
 * Additionally it provides a signal accessor function with last event's value.
 *
 * @param config Emitter configuration: `emitGuard`, `removeGuard`, `beforeEmit` functions and `value` for setting initial value.
 *
 * @returns event bus: `{listen, once, emit, remove, clear, has, value}`
 *
 * @see https://github.com/solidjs-community/solid-primitives/tree/main/packages/event-bus#createEventBus
 *
 * @example
const bus = createEventBus<string>();
// can be destructured:
const { listen, emit, has, clear, value } = bus;

const listener = (event, previous) => console.log(event, previous);
bus.listen(listener);

bus.emit("foo");

bus.remove(listener);
bus.has(listener); // false

// clear all listeners
bus.clear();
 */
declare function createEventBus<Event>(config?: EmitterConfig<Event, Event | undefined> & {
    value?: undefined;
}): EventBus<Event, Event | undefined>;
declare function createEventBus<Event>(config: EmitterConfig<Event, Event> & {
    value: Event;
}): EventBus<Event, Event>;

type PayloadMap<ChannelMap extends Record<string, EventHubChannel>> = {
    [Name in keyof ChannelMap]: Parameters<ChannelMap[Name]["emit"]>;
};
type ValueMap<ChannelMap extends Record<string, EventHubChannel>> = {
    [Name in keyof ChannelMap]: ReturnType<ChannelMap[Name]["value"]>;
};
type EventHubListener<ChannelMap extends Record<string, EventHubChannel>> = (name: keyof ChannelMap, payload: Values<PayloadMap<ChannelMap>>) => void;
type EventHubOn<ChannelMap extends Record<string, EventHubChannel>> = <Name extends keyof ChannelMap>(name: Name, listener: GenericListener<PayloadMap<ChannelMap>[Name]>, protect?: boolean) => VoidFunction;
type EventHubOff<ChannelMap extends Record<string, EventHubChannel>> = <Name extends keyof ChannelMap>(name: Name, listener: GenericListener<PayloadMap<ChannelMap>[Name]>) => boolean;
type EventHubEmit<ChannelMap extends Record<string, EventHubChannel>> = <Name extends keyof ChannelMap>(name: Name, ...payload: PayloadMap<ChannelMap>[Name]) => void;
/**
 * Required interface of a Emitter/EventBus, to be able to be used as a channel in the EventHub
 */
interface EventHubChannel {
    remove: (fn: (...payload: any[]) => void) => boolean;
    listen: (listener: (...payload: any[]) => void, protect?: boolean) => VoidFunction;
    emit: (...payload: any[]) => void;
    clear: VoidFunction;
    value: Accessor<any>;
}
type EventHub<ChannelMap extends Record<string, EventHubChannel>> = ChannelMap & {
    on: EventHubOn<ChannelMap>;
    off: EventHubOff<ChannelMap>;
    emit: EventHubEmit<ChannelMap>;
    clear: (event: keyof ChannelMap) => void;
    clearAll: VoidFunction;
    listen: (listener: EventHubListener<ChannelMap>, protect?: boolean) => VoidFunction;
    remove: (listener: EventHubListener<ChannelMap>) => void;
    clearGlobal: VoidFunction;
    store: ValueMap<ChannelMap>;
};
/**
 * Provides helpers for using a group of emitters.
 *
 * Can be used with `createEmitter`, `createEventBus`, `createEventStack`.
 *
 * @param defineChannels object with defined channels or a defineChannels function returning channels.
 *
 * @returns hub functions: `{on, once, off, emit, clear, clearAll, listen, remove, clearGlobal, store}` + channels available by their key
 *
 * @see https://github.com/solidjs-community/solid-primitives/tree/main/packages/event-bus#createEventHub
 *
 * @example
 * const hub = createEventHub({
 *    busA: createEmitter<void>(),
 *    busB: createEventBus<string>(),
 *    busC: createEventStack<{ text: string }>()
 * });
 * // can be destructured
 * const { busA, busB, on, off, listen, emit, clear } = hub;
 *
 * hub.on("busA", e => {});
 * hub.on("busB", e => {});
 *
 * hub.emit("busA", 0);
 * hub.emit("busB", "foo");
 */
declare function createEventHub<ChannelMap extends Record<string, EventHubChannel>>(defineChannels: ((bus: typeof createEventBus) => ChannelMap) | ChannelMap): EventHub<ChannelMap>;

type EventStackListener<V> = (event: V, stack: V[], removeFromStack: VoidFunction) => void;
type EventStack<E, V = E> = Modify<Emitter<V, V[], VoidFunction>, {
    value: Accessor<V[]>;
    stack: Accessor<V[]>;
    setStack: Setter<V[]>;
    removeFromStack: (value: V) => boolean;
    emit: GenericEmit<[E]>;
}>;
type Config<E, V> = {
    length?: number;
    emitGuard?: EmitterConfig<E>["emitGuard"];
    removeGuard?: EmitterConfig<V, V[], VoidFunction>["removeGuard"];
    beforeEmit?: EmitterConfig<V, V[], VoidFunction>["beforeEmit"];
};
/**
 * Provides all the base functions of an event-emitter, functions for managing listeners, it's behavior could be customized with an config object.
 * Additionally it provides the emitted events in a list/history form, with tools to manage it.
 *
 * @param config Emitter configuration: `emitGuard`, `removeGuard`, `beforeEmit` functions and `toValue` parsing event to a value in stack.
 *
 * @returns event stack: `{listen, once, emit, remove, clear, has, stack, setStack, removeFromStack}`
 *
 * @see https://github.com/solidjs-community/solid-primitives/tree/main/packages/event-bus#createEventStack
 *
 * @example
const bus = createEventStack<{ message: string }>();
// can be destructured:
const { listen, emit, has, clear, stack } = bus;

const listener: EventStackListener<{ text: string }> = (event, stack, removeValue) => {
  console.log(event, stack);
  // you can remove the value from stack
  removeValue();
};
bus.listen(listener);

bus.emit({text: "foo"});

// a signal accessor:
bus.stack() // => { text: string }[]

bus.removeFromStack(value) // pass a reference to the value

bus.setStack(stack => stack.filter(item => {...}))
 */
declare function createEventStack<E extends object>(config?: Config<E, E>): EventStack<E, E>;
declare function createEventStack<E, V extends object>(config: Config<E, V> & {
    toValue: (event: E, stack: V[]) => V;
}): EventStack<E, V>;

type _PromiseValue<T extends any[]> = void extends T[1] ? T[0] : T;
/**
 * Turns a stream-like listen function, into a promise resolving when the first event is captured.
 * @param subscribe listen function from any EventBus/Emitter
 * @returns a promise resulting in the captured event value
 * @example
 * const emitter = createEmitter<string>();
 * const event = await toPromise(emitter.listen);
 */
declare function toPromise<T extends any[]>(subscribe: GenericListen<T>): Promise<_PromiseValue<T>>;
declare function toPromise<T extends any[]>(subscribe: GenericListenProtect<T>, protect?: boolean): Promise<_PromiseValue<T>>;
/**
 * Listen to any EventBus/Emitter, but the listener will automatically unsubscribe on the first captured event. So the callback will run only **once**.
 *
 * @param subscribe Emitter's `listen` function
 * @param listener callback called when an event is emitted
 *
 * @returns unsubscribe function
 *
 * @example
 * const { listen, emit } = createEmitter<string>();
 * const unsub = once(listen, event => console.log(event));
 *
 * emit("foo") // will log "foo" and unsub
 *
 * emit("bar") // won't log
 */
declare function once<T extends any[] = []>(subscribe: GenericListen<T>, listener: GenericListener<T>): VoidFunction;
declare function once<T extends any[] = []>(subscribe: GenericListenProtect<T>, listener: GenericListener<T>, protect?: boolean): VoidFunction;
/**
 * Wraps `emit` calls inside a `createEffect`. It causes that listeners execute having an reactive owner available. It allows for usage of effects, memos and other primitives inside listeners, without having to create a synthetic root.
 *
 * @param emit the emit function of any emitter/event-bus
 * @returns modified emit function
 *
 * @example
 * const { listen, emit } = createEmitter();
 * const emitInEffect = toEffect(emit);
 * listen(() => console.log(getOwner()))
 *
 * // ...sometime later (after root initiation):
 * emit() // listener will log `null`
 * emitInEffect() // listener will log an owner object
 */
declare function toEffect<T extends any[]>(emit: GenericEmit<T>): GenericEmit<T>;

export { Emit, EmitGuard, Emitter, EmitterConfig, EventBus, EventBusListen, EventBusListener, EventBusRemove, EventHub, EventHubChannel, EventHubEmit, EventHubListener, EventHubOff, EventHubOn, EventStack, EventStackListener, GenericEmit, GenericListen, GenericListenProtect, GenericListener, Listen, ListenProtect, Remove, RemoveGuard, createEmitter, createEventBus, createEventHub, createEventStack, createSimpleEmitter, once, toEffect, toPromise };
